/**
 * Performance-budgeted prefix search index.
 *
 * Index layout (built once, O(total tokens)):
 *   tokens -> Map<lowercased token, Set<id>>   exact-token membership
 *   fields -> Map<id, { title: Set<token>, tags: Set<token> }>
 *
 * search(index, query):
 *   - each query word does prefix matching against the token vocabulary
 *     via a sorted-array binary scan over all unique tokens
 *   - a record matches if EVERY query word matches at least one of its
 *     fields (AND semantics)
 *   - results are ranked by number of distinct matching fields (desc),
 *     ties broken by id for determinism
 */

const TOKEN_RE = /[^a-z0-9]+/;

/** Split a string into lowercased alphanumeric tokens. */
function tokenize(value) {
  return String(value).toLowerCase().split(TOKEN_RE).filter(Boolean);
}

/**
 * Build a searchable index from records of shape { id, title, tags }.
 * @param {Array<{id: number|string, title: string, tags: string[]}>} records
 */
export function buildIndex(records) {
  // Sorted unique token vocabulary for O(log n) prefix expansion.
  const vocab = new Set();
  // Per-record field -> set of tokens in that field.
  const fieldTokens = new Map();

  for (const rec of records) {
    const title = new Set(tokenize(rec.title));
    const tags = new Set();
    for (const tag of rec.tags || []) {
      for (const t of tokenize(tag)) tags.add(t);
    }
    for (const t of title) vocab.add(t);
    for (const t of tags) vocab.add(t);
    fieldTokens.set(rec.id, { title, tags });
  }

  const tokens = [...vocab].sort();

  return { tokens, fieldTokens };
}

/**
 * Expand a query word to all vocabulary tokens that start with it,
 * using binary search on the sorted vocabulary.
 * @returns {string[]} matched tokens (possibly empty)
 */
function prefixExpand(tokens, word) {
  let lo = 0;
  let hi = tokens.length;
  // lower bound: first index with tokens[i] >= word
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (tokens[mid] < word) lo = mid + 1;
    else hi = mid;
  }
  const start = lo;
  const out = [];
  while (start + out.length < tokens.length && tokens[start + out.length].startsWith(word)) {
    out.push(tokens[start + out.length]);
  }
  return out;
}

/**
 * Search the index. Every query word must match at least one field of a
 * record (AND). Ranked by number of matching distinct fields (title/tags),
 * then by id ascending.
 * @returns {Array<number|string>} matching ids, best first
 */
export function search(index, query) {
  const words = tokenize(query);
  if (words.length === 0) return [];

  const { tokens, fieldTokens } = index;

  // For each query word: set of candidate ids having that word in any field.
  /** @type {Array<Map<string|number, number>>} word -> id -> #fields hit by this word */
  const perWord = [];
  for (const w of words) {
    const hits = new Map();
    for (const tok of prefixExpand(tokens, w)) {
      for (const [id, fields] of fieldTokens) {
        let f = 0;
        if (fields.title.has(tok)) f++;
        if (fields.tags.has(tok)) f++;
        if (f > 0) hits.set(id, (hits.get(id) || 0) + f);
      }
    }
    if (hits.size === 0) return []; // AND semantics: one unmatched word kills all
    perWord.push(hits);
  }

  if (perWord.length === 1) {
    return [...perWord[0].entries()]
      .sort((a, b) => b[1] - a[1] || String(a[0]).localeCompare(String(b[0])))
      .map(([id]) => id);
  }

  // Intersect candidates across words; score = sum of per-word field hits.
  const [first, ...rest] = perWord;
  first.sort((a, b) => a - b); // placeholder to keep Map insertion order irrelevant
  const scores = new Map();
  outer: for (const [id, f0] of first) {
    let total = f0;
    for (const other of rest) {
      const f = other.get(id);
      if (f === undefined) continue outer;
      total += f;
    }
    scores.set(id, total);
  }

  return [...scores.entries()]
    .sort((a, b) => b[1] - a[1] || String(a[0]).localeCompare(String(b[0])))
    .map(([id]) => id);
}

/**
 * Naive reference implementation: linear scan over all records per query.
 * Same semantics as `search`. Exists so tests can prove the indexed path
 * is actually faster than brute force.
 */
export function naiveSearch(records, query) {
  const words = tokenize(query);
  if (words.length === 0) return [];

  const results = [];
  for (const rec of records) {
    const titleTokens = tokenize(rec.title);
    const tagTokens = (rec.tags || []).flatMap((t) => tokenize(t));
    let total = 0;
    let allMatched = true;
    for (const w of words) {
      let f = 0;
      if (titleTokens.some((t) => t.startsWith(w))) f++;
      if (tagTokens.some((t) => t.startsWith(w))) f++;
      if (f === 0) {
        allMatched = false;
        break;
      }
      total += f;
    }
    if (allMatched) results.push([rec.id, total]);
  }

  return results
    .sort((a, b) => b[1] - a[1] || String(a[0]).localeCompare(String(b[0])))
    .map(([id]) => id);
}

