/**
 * Deterministic generator: seeded PRNG (mulberry32), 50000 records
 * of shape { id, title, tags }.
 */
import { writeFileSync } from 'node:fs';

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const ADJ = [
  'rapid', 'quiet', 'brisk', 'lunar', 'solar', 'amber', 'cobalt', 'crimson',
  'golden', 'silent', 'frozen', 'hidden', 'jagged', 'misty', 'noble', 'polar',
  'rustic', 'subtle', 'vivid', 'zesty', 'urban', 'wild', 'keen', 'vast',
];
const NOUN = [
  'falcon', 'harbor', 'meadow', 'summit', 'canyon', 'glacier', 'orchard', 'tundra',
  'prairie', 'reef', 'ridge', 'valley', 'lagoon', 'plateau', 'basin', 'forest',
  'delta', 'island', 'steppe', 'mesa',
];
const TAGS = [
  'alpha', 'beta', 'gamma', 'delta', 'omega', 'prime', 'core', 'edge',
  'flux', 'nova', 'apex', 'helix', 'quark', 'photon', 'vector', 'matrix',
];

/**
 * Generate `n` deterministic records.
 * @param {number} n
 * @param {number} seed
 */
export function generateRecords(n = 50000, seed = 42) {
  const rand = mulberry32(seed);
  const records = [];
  for (let i = 0; i < n; i++) {
    const adj = ADJ[Math.floor(rand() * ADJ.length)];
    const noun = NOUN[Math.floor(rand() * NOUN.length)];
    const tagCount = 1 + Math.floor(rand() * 3);
    const tags = [];
    for (let k = 0; k < tagCount; k++) {
      tags.push(TAGS[Math.floor(rand() * TAGS.length)]);
    }
    records.push({ id: i, title: `${adj} ${noun} ${i}`, tags });
  }
  return records;
}

// CLI entry: writes a sample JSON for inspection.
if (import.meta.url === `file://${process.argv[1]}`) {
  const records = generateRecords(50000, 42);
  writeFileSync(new URL('./records.json', import.meta.url), JSON.stringify(records));
  console.log(`wrote ${records.length} records`);
}

