/**
 * Performance-budgeted prefix search index.
 *
 * Index layout (built once, O(total tokens)):
 *   tokens    : sorted array of unique lowercased vocabulary tokens
 *   postTitle : Map<token, id[]>  ids of records whose title has this token
 *   postTags  : Map<token, id[]>  ids of records whose tags have this token
 *
 * search(index, query):
 *   - every query word is expanded to all vocabulary tokens sharing the
 *     prefix (binary search on the sorted vocabulary)
 *   - a record matches if EVERY query word matches at least one field
 *     (AND semantics across words)
 *   - results ranked by number of matching fields (title/tags) summed
 *     over query words; ties broken by id for determinism
 */

const TOKEN_RE = /[^a-z0-9]+/;

/** Split a string into lowercased alphanumeric tokens. */
function tokenize(value) {
  return String(value).toLowerCase().split(TOKEN_RE).filter(Boolean);
}

/**
 * Build a searchable index from records of shape { id, title, tags }.
 * @param {Array<{id: number|string, title: string, tags: string[]}>} records
 */
export function buildIndex(records) {
  const vocab = new Set();
  /** @type {Map<string, Array<number|string>>} */
  const postTitle = new Map();
  /** @type {Map<string, Array<number|string>>} */
  const postTags = new Map();

  for (const rec of records) {
    const titleTokens = tokenize(rec.title);
    const tagTokens = (rec.tags || []).flatMap((t) => tokenize(t));
    for (const t of titleTokens) vocab.add(t);
    for (const t of tagTokens) vocab.add(t);
    for (const t of titleTokens) {
      let list = postTitle.get(t);
      if (!list) postTitle.set(t, (list = []));
      list.push(rec.id);
    }
    for (const t of tagTokens) {
      // avoid duplicate ids when the same tag token repeats on a record
      let list = postTags.get(t);
      if (!list) postTags.set(t, (list = []));
      if (list.length === 0 || list[list.length - 1] !== rec.id || !list.includes(rec.id)) {
        if (!list.includes(rec.id)) list.push(rec.id);
      }
    }
  }

  return { tokens: [...vocab].sort(), postTitle, postTags };
}

/**
 * Expand a query word to all vocabulary tokens starting with it,
 * via binary search (lower bound) on the sorted vocabulary.
 * @returns {string[]}
 */
export function prefixExpand(tokens, word) {
  let lo = 0;
  let hi = tokens.length;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (tokens[mid] < word) lo = mid + 1;
    else hi = mid;
  }
  const out = [];
  while (lo + out.length < tokens.length && tokens[lo + out.length].startsWith(word)) {
    out.push(tokens[lo + out.length]);
  }
  return out;
}

/** Per-word candidate map: id -> bitmask of matched fields (1=title, 2=tags). */
function wordCandidates(index, word) {
  const cand = new Map();
  for (const tok of prefixExpand(index.tokens, word)) {
    const tl = index.postTitle.get(tok);
    if (tl) for (const id of tl) cand.set(id, cand.get(id) | 1);
    const gl = index.postTags.get(tok);
    if (gl) for (const id of gl) cand.set(id, cand.get(id) | 2);
  }
  return cand;
}

const popcount2 = (m) => (m & 1) + ((m >> 1) & 1);

/**
 * Search the index with AND semantics and field-count ranking.
 * @returns {Array<number|string>} matching ids, best first
 */
export function search(index, query) {
  const words = tokenize(query);
  if (words.length === 0) return [];

  const perWord = words.map((w) => wordCandidates(index, w));
  if (perWord.some((m) => m.size === 0)) return []; // AND: one miss kills all

  // Intersect smallest-first to keep the working set tiny.
  perWord.sort((a, b) => a.size - b.size);
  const [smallest, ...rest] = perWord;

  const scored = [];
  outer: for (const [id, mask0] of smallest) {
    let score = popcount2(mask0);
    for (const other of rest) {
      const mask = other.get(id);
      if (mask === undefined) continue outer;
      score += popcount2(mask);
    }
    scored.push([id, score]);
  }

  scored.sort((a, b) => b[1] - a[1] || String(a[0]).localeCompare(String(b[0])));
  return scored.map(([id]) => id);
}

/**
 * Naive reference implementation: full linear scan over records per query.
 * Same semantics as `search`. Used by tests to prove the indexed path is
 * strictly faster than brute force.
 * @param {Array<{id: number|string, title: string, tags: string[]}>} records
 */
export function naiveSearch(records, query) {
  const words = tokenize(query);
  if (words.length === 0) return [];

  const results = [];
  for (const rec of records) {
    const titleTokens = tokenize(rec.title);
    const tagTokens = (rec.tags || []).flatMap((t) => tokenize(t));
    let total = 0;
    let ok = true;
    for (const w of words) {
      let f = 0;
      if (titleTokens.some((t) => t.startsWith(w))) f++;
      if (tagTokens.some((t) => t.startsWith(w))) f++;
      if (f === 0) {
        ok = false;
        break;
      }
      total += f;
    }
    if (ok) results.push([rec.id, total]);
  }

  results.sort((a, b) => b[1] - a[1] || String(a[0]).localeCompare(String(b[0])));
  return results.map(([id]) => id);
}

