const popcount2 = (m) => (m & 1) + ((m >> 1) & 1);

/**
 * Search the index with AND semantics and field-count ranking.
 * @returns {Array<number|string>} matching ids, best first
 */
export function search(index, query) {
  const words = tokenize(query);
  if (words.length === 0) return [];

  const perWord = words.map((w) => wordCandidates(index, w));
  if (perWord.some((m) => m.size === 0)) return []; // AND: one miss kills all

  // Intersect smallest-first to keep the working set tiny.
  perWord.sort((a, b) => a.size - b.size);
  const [smallest, ...rest] = perWord;

  const scored = [];
  outer: for (const [id, mask0] of smallest) {
    let score = popcount2(mask0);
    for (const other of rest) {
      const mask = other.get(id);
      if (mask === undefined) continue outer;
      score += popcount2(mask);
    }
    scored.push([id, score]);
  }

  scored.sort((a, b) => b[1] - a[1] || String(a[0]).localeCompare(String(b[0])));
  return scored.map(([id]) => id);
}

/**
 * Naive reference implementation: full linear scan over records per query.
 * Same semantics as `search`. Used by tests to prove the indexed path is
 * strictly faster than brute force.
 * @param {Array<{id: number|string, title: string, tags: string[]}>} records
 */
export function naiveSearch(records, query) {
  const words = tokenize(query);
  if (words.length === 0) return [];

  const results = [];
  for (const rec of records) {
    const titleTokens = tokenize(rec.title);
    const tagTokens = (rec.tags || []).flatMap((t) => tokenize(t));
    let total = 0;
    let ok = true;
    for (const w of words) {
      let f = 0;
      if (titleTokens.some((t) => t.startsWith(w))) f++;
      if (tagTokens.some((t) => t.startsWith(w))) f++;
      if (f === 0) {
        ok = false;
        break;
      }
      total += f;
    }
    if (ok) results.push([rec.id, total]);
  }

  results.sort((a, b) => b[1] - a[1] || String(a[0]).localeCompare(String(b[0])));
  return results.map(([id]) => id);
}
