import { describe, it, expect } from 'vitest';
import { buildIndex, search, naiveSearch, prefixExpand } from '../src/index.js';
import { generateRecords } from '../src/gen.js';

describe('correctness (handcrafted set)', () => {
  const records = [
    { id: 1, title: 'Rapid Falcon', tags: ['alpha', 'nova'] },
    { id: 2, title: 'Quiet Falcon', tags: ['beta'] },
    { id: 3, title: 'Rapid Harbor', tags: ['gamma'] },
    { id: 4, title: 'Rapid Ridge', tags: ['alpha'] },
    { id: 5, title: 'Slow Turtle', tags: ['delta', 'alpha prime'] },
  ];
  const index = buildIndex(records);

  it('matches a single word by prefix', () => {
    expect(search(index, 'fal')).toEqual([1, 2]);
  });

  it('applies AND semantics across words', () => {
    // both words must match somewhere in the record
    expect(search(index, 'rapid alpha')).toEqual([1, 4]);
    expect(search(index, 'quiet nova')).toEqual([]); // no record has both
    expect(search(index, 'falcon rapid')).toEqual([1, 2]); // order-independent
  });

  it('ranks by number of matching fields, ties by id', () => {
    // "rapid" matches title of 1,3,4; "alpha" matches tags of 1,4,5.
    // ids 1 and 4 match two fields (score 2), tie broken by id: 1 then 4.
    expect(search(index, 'rapid alpha')).toEqual([1, 4]);
  });

  it('counts a field once even if several prefix tokens hit it', () => {
    // "al" expands to {alpha}; record 5 matches only via tags -> score 1
    expect(naiveSearch(records, 'turtle al')).toEqual([5]);
    expect(search(index, 'turtle al')).toEqual([5]);
  });

  it('is case-insensitive and tokenizes punctuation', () => {
    expect(search(index, 'RAPID')).toEqual([1, 3, 4]);
    expect(search(index, 'prime!')).toEqual([5]);
  });

  it('returns [] for empty or unmatched queries', () => {
    expect(search(index, '')).toEqual([]);
    expect(search(index, '   ')).toEqual([]);
    expect(search(index, 'zebra')).toEqual([]);
    expect(search(index, 'rapid zebra')).toEqual([]);
  });

  it('prefix expansion finds the expected vocabulary slice', () => {
    const vocab = buildIndex(records).tokens;
    expect(prefixExpand(vocab, 'ra')).toEqual(['rapid']);
    expect(prefixExpand(vocab, 'q')).toEqual(['quiet']);
    expect(prefixExpand(vocab, 'zz')).toEqual([]);
  });

  it('indexed search agrees with the naive scan on every handcrafted query', () => {
    for (const q of [
      'rapid', 'alpha', 'rapid alpha', 'fal', 'harbor gamma',
      'slow delta', 'turtle', 'a', 'rapid quiet',
    ]) {
      expect(search(index, q)).toEqual(naiveSearch(records, q));
    }
  });
});

describe('performance budget (50k records)', () => {
  const records = generateRecords(50000, 42);
  const index = buildIndex(records);

  // 200 varied queries: short prefixes (broad), full tokens (narrow),
  // multi-word ANDs, some with no matches at all.
  const ADJ = ['r', 'ra', 'qui', 'gold', 'lun', 'misty', 'vivid', 'zest'];
  const NOUN = ['falc', 'harbo', 'mead', 'summit', 'can', 'glacier', 'tund'];
  const TAGS = ['alp', 'be', 'gam', 'omeg', 'nov', 'helix'];
  const queries = [];
  let s = 7;
  const rnd = () => ((s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
  for (let i = 0; i < 200; i++) {
    const a = ADJ[Math.floor(rnd() * ADJ.length)];
    const n = NOUN[Math.floor(rnd() * NOUN.length)];
    const t = TAGS[Math.floor(rnd() * TAGS.length)];
    switch (i % 4) {
      case 0: queries.push(a); break;
      case 1: queries.push(`${n}`); break;
      case 2: queries.push(`${a} ${t}`); break;
      case 3: queries.push(`${n} ${t} zzqq`); break; // guaranteed no match
    }
  }

  it('runs 200 queries in under 300ms total (build excluded)', () => {
    // warmup (JIT) outside the measured window
    for (const q of queries.slice(0, 20)) search(index, q);

    const t0 = performance.now();
    for (const q of queries) search(index, q);
    const elapsed = performance.now() - t0;

    // eslint-disable-next-line no-console
    console.log(`indexed: 200 queries in ${elapsed.toFixed(2)}ms`);
    expect(elapsed).toBeLessThan(300);
  });

  it('indexed path is at least 5x faster than a naive linear scan', () => {
    const t0 = performance.now();
    for (const q of queries) naiveSearch(records, q);
    const naiveMs = performance.now() - t0;

    const t1 = performance.now();
    for (const q of queries) search(index, q);
    const indexedMs = performance.now() - t1;

    // eslint-disable-next-line no-console
    console.log(
      `naive: ${naiveMs.toFixed(2)}ms vs indexed: ${indexedMs.toFixed(2)}ms ` +
      `(${(naiveMs / indexedMs).toFixed(1)}x)`
    );
    // honesty check: brute force must be slow enough that the budget test
    // cannot be satisfied by a linear scan
    expect(naiveMs).toBeGreaterThan(300);
    expect(indexedMs).toBeLessThan(naiveMs / 5);
  });

  it('indexed results are consistent with the naive scan on sampled queries', () => {
    for (const q of ['rapid', 'meadow alpha', 'glacier beta', 'zzqq']) {
      const fast = search(index, q);
      const slow = naiveSearch(records, q);
      expect(fast.slice(0, 50)).toEqual(slow.slice(0, 50));
    }
  });
});

